    mul.wide.u32 %rd5, %r2, %r1;   // rd5 = bid*n (64-bit)
    shl.b64 %rd6, %rd5, 2;         // rd6 = bytes offset

    add.u64 %rd7, %rd1, %rd6;      // base_x
    add.u64 %rd8, %rd2, %rd6;      // base_y

    // ---- Pass 1: compute partial sum and sum of squares (vectorized) ----
    mov.f32 %f2, 0f00000000;   // sum
    mov.f32 %f3, 0f00000000;   // sumsq
    shr.u32 %r11, %r1, 2;      // nQuad = n / 4
    shl.b32 %r9, %r11, 2;      // tailStart = nQuad * 4
    mov.u32 %r5, %r3;          // quad index = tid
LOOP1V:
    setp.ge.u32 %p1, %r5, %r11;
    @%p1 bra LOOP1V_END;
    mul.wide.u32 %rd9, %r5, 16;
    add.u64 %rd10, %rd7, %rd9;
    ld.global.v4.f32 {%f4, %f5, %f6, %f7}, [%rd10];
    add.f32 %f2, %f2, %f4;
    add.f32 %f2, %f2, %f5;
    add.f32 %f2, %f2, %f6;
    add.f32 %f2, %f2, %f7;
    fma.rn.f32 %f3, %f4, %f4, %f3;
    fma.rn.f32 %f3, %f5, %f5, %f3;
    fma.rn.f32 %f3, %f6, %f6, %f3;
    fma.rn.f32 %f3, %f7, %f7, %f3;
    add.u32 %r5, %r5, %r4;
    bra LOOP1V;
LOOP1V_END:
    add.u32 %r10, %r9, %r3;    // tail index = tailStart + tid
LOOP1T:
    setp.ge.u32 %p5, %r10, %r1;
    @%p5 bra LOOP1_END;
    mul.wide.u32 %rd40, %r10, 4;
    add.u64 %rd41, %rd7, %rd40;
    ld.global.f32 %f8, [%rd41];
    add.f32 %f2, %f2, %f8;
    fma.rn.f32 %f3, %f8, %f8, %f3;
    add.u32 %r10, %r10, %r4;
    bra LOOP1T;
LOOP1_END:

    mul.wide.u32 %rd11, %r3, 4;
    mov.u64 %rd12, s_sum;
    add.u64 %rd13, %rd12, %rd11;
    st.shared.f32 [%rd13], %f2;

    mov.u64 %rd14, s_sq;
    add.u64 %rd15, %rd14, %rd11;
    st.shared.f32 [%rd15], %f3;

    bar.sync 0;

    // ---- Tree reduction ----
    mov.u32 %r6, 128;

