    setp.eq.u32 %p2, %r6, 0;
    @%p2 bra REDUCE_END;

    setp.ge.u32 %p3, %r3, %r6;
    @%p3 bra SKIP_REDUCE;

    mul.wide.u32 %rd16, %r3, 4;
    mov.u64 %rd17, s_sum;
    add.u64 %rd18, %rd17, %rd16;
    ld.shared.f32 %f5, [%rd18];

    add.u32 %r7, %r3, %r6;
    mul.wide.u32 %rd19, %r7, 4;
    add.u64 %rd20, %rd17, %rd19;
    ld.shared.f32 %f6, [%rd20];

    add.f32 %f5, %f5, %f6;
    st.shared.f32 [%rd18], %f5;

    mov.u64 %rd21, s_sq;
    add.u64 %rd22, %rd21, %rd16;
    ld.shared.f32 %f7, [%rd22];

    add.u64 %rd23, %rd21, %rd19;
    ld.shared.f32 %f8, [%rd23];

    add.f32 %f7, %f7, %f8;
    st.shared.f32 [%rd22], %f7;

SKIP_REDUCE:
    bar.sync 0;
    shr.u32 %r6, %r6, 1;
    bra REDUCE_LOOP;

REDUCE_END:

    mov.u64 %rd24, s_sum;
    ld.shared.f32 %f9, [%rd24];
    mov.u64 %rd25, s_sq;
    ld.shared.f32 %f10, [%rd25];

    cvt.rn.f32.u32 %f11, %r1;    // n as float

    div.rn.f32 %f12, %f9, %f11;     // mean
