    sub.f32 %f15, %f13, %f14;       // variance
    add.f32 %f16, %f15, %f1;        // var + eps
    sqrt.rn.f32 %f17, %f16;         // std
    mov.f32 %f18, 0f3F800000;       // 1.0
    div.rn.f32 %f19, %f18, %f17;    // invstd

    // ---- Pass 2: normalize and write output (vectorized) ----
    mov.u32 %r20, %r3;   // quad index = tid
