    setp.ge.u32 %p6, %r20, %r11;
    @%p6 bra LOOP2V_END;
    mul.wide.u32 %rd43, %r20, 16;
    add.u64 %rd44, %rd7, %rd43;
    ld.global.v4.f32 {%f20, %f21, %f22, %f23}, [%rd44];
    add.u64 %rd45, %rd3, %rd43;
    ld.global.v4.f32 {%f24, %f25, %f26, %f27}, [%rd45];
    add.u64 %rd46, %rd4, %rd43;
    ld.global.v4.f32 {%f28, %f29, %f30, %f31}, [%rd46];
    sub.f32 %f32, %f20, %f12;
    mul.f32 %f32, %f32, %f19;
    fma.rn.f32 %f32, %f32, %f24, %f28;
    sub.f32 %f33, %f21, %f12;
    mul.f32 %f33, %f33, %f19;
    fma.rn.f32 %f33, %f33, %f25, %f29;
    sub.f32 %f34, %f22, %f12;
    mul.f32 %f34, %f34, %f19;
    fma.rn.f32 %f34, %f34, %f26, %f30;
    sub.f32 %f35, %f23, %f12;
    mul.f32 %f35, %f35, %f19;
    fma.rn.f32 %f35, %f35, %f27, %f31;
    add.u64 %rd47, %rd8, %rd43;
    st.global.v4.f32 [%rd47], {%f32, %f33, %f34, %f35};
    add.u32 %r20, %r20, %r4;
    bra LOOP2V;
LOOP2V_END:
    add.u32 %r21, %r9, %r3;   // tail index = tailStart + tid
LOOP2T:
    setp.ge.u32 %p7, %r21, %r1;
    @%p7 bra LOOP2_END;
    mul.wide.u32 %rd48, %r21, 4;
    add.u64 %rd49, %rd7, %rd48;
    ld.global.f32 %f36, [%rd49];
    add.u64 %rd50, %rd3, %rd48;
    ld.global.f32 %f37, [%rd50];
    add.u64 %rd51, %rd4, %rd48;
    ld.global.f32 %f38, [%rd51];
    sub.f32 %f39, %f36, %f12;
    mul.f32 %f39, %f39, %f19;
    fma.rn.f32 %f39, %f39, %f37, %f38;
    add.u64 %rd52, %rd8, %rd48;
    st.global.f32 [%rd52], %f39;
    add.u32 %r21, %r21, %r4;
    bra LOOP2T;
LOOP2_END:

    ret;
}
